object Solution {
  def maximumANDSum(nums: Array[Int], numSlots: Int): Int = {
    val n = nums.length
    // Each slot can hold up to 2 numbers, so total capacity = 2 * numSlots >= n
    // We represent the state as a bitmask with 2 bits per slot indicating how many numbers are placed in that slot.
    // For example, for slot i (0-based), bits (2*i) and (2*i+1) represent count of numbers in that slot (0 to 2).
    // We'll use DP with memoization: dp(i, mask) = max AND sum placing nums[i..] given current mask state.

    import scala.collection.mutable

    val maxMask = 1 << (2 * numSlots) // max mask value (not used directly, but for clarity)

    val memo = mutable.Map.empty[(Int, Int), Int]

    def getCount(mask: Int, slot: Int): Int = {
      // Extract 2 bits for slot
      (mask >> (2 * slot)) & 3
    }

    def setCount(mask: Int, slot: Int, count: Int): Int = {
      // Clear 2 bits for slot and set new count
      val cleared = mask & ~(3 << (2 * slot))
      cleared | (count << (2 * slot))
    }

    def dfs(i: Int, mask: Int): Int = {
      if (i == n) return 0
      if (memo.contains((i, mask))) return memo((i, mask))

      var best = 0
      val num = nums(i)
      for (slot <- 0 until numSlots) {
        val c = getCount(mask, slot)
        if (c < 2) {
          val newMask = setCount(mask, slot, c + 1)
          val valAnd = num & (slot + 1)
          val candidate = valAnd + dfs(i + 1, newMask)
          if (candidate > best) best = candidate
        }
      }
      memo((i, mask)) = best
      best
    }

    dfs(0, 0)
  }
}

